n = int(input())
a = list(map(int, input().split()))
b = list(map(int, input().split()))
sa = sum(a)
sb = sum(b)
if sb < sa:
    print('No')
else:
    resb = 0
    ref_cb = 0
    for i in range(n):
        if b[i] < a[i]:
            ref_cb += a[i] - b[i]
        else:
            resb += (b[i] - a[i] + 1) // 2
            ref_cb += (b[i] - a[i]) % 2
    ref_x = sum(b) - sum(a)
    if ref_x >= resb and ref_x >= ref_cb and ((ref_x - resb) * 2 == ref_x - ref_cb):
        print('Yes')
    else:
        print('No')

