    N = I()
    a = LI()
    b = LI()

    # 全てのiに対してa[i]<=b[i]にしていく
    tmp = 0
    for i in range(N):
        if a[i] > b[i]:
            tmp += a[i] - b[i]
        else:
            tmp -= (b[i] - a[i]) // 2

    if tmp <= 0:
        print('Yes')
    else:
        print('No')

if __name__ == '__main__':
    resolve()

