def input(): return sys.stdin.readline().strip()


def resolve():
    N = int(input())
    A = list(map(int, input().split()))
    B = list(map(int, input().split()))

    biggerA = 0
    biggerB=0

    for i in range(N):
        if A[i] > B[i]:
            biggerA += A[i] - B[i]
        if A[i] < B[i]:
            biggerB += B[i] - A[i]

    if biggerA * 2 <= biggerB:
        print('Yes')
    else:
        print('No')


resolve()

import sys
import math  # noqa
import bisect  # noqa
import queue  # noqa


def input():
    return sys.stdin.readline().rstrip()


def main():
    _ = int(input())
    A = list(map(int, input().split()))
    B = list(map(int, input().split()))

    D = [b - a for a, b in zip(A, B)]
    neg = 0
    pos = 0
    for d in D:
        if d < 0:
            neg -= d
        elif d > 1:
            pos += d

    if pos < neg * 2:
        print("No")
    else:
        print("Yes")


if __name__ == '__main__':
    main()

